{
  "name": "status-provider",
  "version": "0.3.1",
  "packageManager": "bun@1.3.4",
  "description": "OpenCode plugin and CLI for provider usage status, quota windows, runtime diagnostics, sidebar/TUI panels, and configurable display previews across AI providers.",
  "type": "module",
  "main": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "bin": {
    "status-provider": "./dist/bin/status-provider.js"
  },
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "default": "./dist/index.js"
    },
    "./server": {
      "types": "./dist/index.d.ts",
      "default": "./dist/index.js"
    },
    "./tui": {
      "types": "./dist/tui.d.ts",
      "default": "./dist/tui.js"
    }
  },
  "oc-plugin": [
    "server",
    "tui"
  ],
  "files": [
    "dist",
    "README.md",
    "LICENSE"
  ],
  "publishConfig": {
    "access": "public"
  },
  "scripts": {
    "build": "tsc && node scripts/copy-data.mjs && node scripts/prepare-tui-dist.mjs",
    "build:check": "bun run build && bun pm pack --dry-run",
    "pricing:refresh": "node scripts/refresh-modelsdev-pricing.mjs",
    "pricing:refresh:if-stale": "node scripts/refresh-modelsdev-pricing-if-stale.mjs",
    "upstream:check": "node scripts/check-upstream-plugin-updates.mjs",
    "upstream:prepare-review": "node scripts/prepare-upstream-plugin-review.mjs",
    "upstream:sync": "node scripts/sync-upstream-plugin-references.mjs",
    "verify:release-version": "node scripts/verify-release-version.mjs",
    "typecheck": "tsc --noEmit",
    "test": "vitest run",
    "test:watch": "vitest",
    "prepublishOnly": "bun run build"
  },
  "keywords": [
    "opencode",
    "plugin",
    "status",
    "toast",
    "github",
    "copilot",
    "google",
    "antigravity",
    "gemini",
    "claude",
    "MiniMax",
    "minimax",
    "anthropic",
    "retry-after",
    "rate-limit"
  ],
  "author": "MrDyslexia <mhhernand@gmail.com>",
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/MrDyslexia/status-provider.git"
  },
  "bugs": {
    "url": "https://github.com/MrDyslexia/status-provider/issues"
  },
  "homepage": "https://github.com/MrDyslexia/status-provider#readme",
  "devDependencies": {
    "@babel/core": "7.29.7",
    "@babel/preset-typescript": "7.29.7",
    "@opencode-ai/plugin": "1.17.15",
    "@types/node": "22.20.0",
    "babel-preset-solid": "1.9.12",
    "prettier": "3.8.4",
    "typescript": "5.9.3",
    "vitest": "4.1.9"
  },
  "dependencies": {
    "@clack/prompts": "1.6.0",
    "@opentui/core": "0.2.16",
    "@opentui/solid": "0.2.16",
    "comment-json": "5.0.0",
    "solid-js": "1.9.13",
    "xdg-basedir": "5.1.0"
  },
  "peerDependencies": {
    "@opencode-ai/plugin": "1.17.15"
  },
  "engines": {
    "node": ">=18.0.0"
  }
}
